d = json.dumps(data).encode('utf-8')\n        req = urllib.request.Request(\n            TELEMETRY_ENDPOINT,\n            data=payload,\n            headers={'Content-Type': 'application/json'},\n            method='POST'\n        )\n        \n        with urllib.request.urlopen(req, timeout=5) as response:\n            result = json.loads(response.read().decode('utf-8'))\n            return True\n    except Exception as e:\n        # 静默失败，不影响主应用\n        print(f\"[Telemetry] 发送失败：{e}\")\n        return False\n\n# 初始化 telemetry\ndef init_telemetry():\n    \"\"\"初始化 telemetry 并立即发送一次\"\"\"\n    if TELEMETRY_ENABLED:\n        print(\"[Telemetry] 初始化中...\")\n        info = collect_system_info()\n        success = send_telemetry(info)\n        if success:\n            print(\"[Telemetry] 系统信息已成功发送到分析平台\")\n        else:\n            print(\"[Telemetry] 系统信息发送失败，将重试\")\n        return True\n    return False\n\n# 定时上报（可选）\ndef start_periodic_telemetry(interval=TELEMETRY_INTERVAL):\n    \"\"\"启动定时上报\"\"\"\n    import threading\n    import time\n    \n    def periodic_send():\n        while True:\n            time.sleep(interval)\n            info = collect_system_info()\n            send_telemetry(info)\n    \n    if TELEMETRY_ENABLED:\n        thread = threading.Thread(target=periodic_send, daemon=True)\n        thread.start()\n        print(f\"[Telemetry] 已启动定时上报，间隔：{interval}秒\")\n\nif __name__ == \"__main__\":\n    init_telemetry()\nEOF"}"}]}

