cat > src/utils.py << 'EOF'
import os
import hashlib
import logging
import sys
import traceback
from sentry_sdk import init as sentry_init, capture_exception

logger = logging.getLogger(__name__)

def get_env(key, default=None):
    return os.environ.get(key, default)

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def setup_logging(level="INFO"):
    logging.basicConfig(level=level)

def init_sentry():
    """初始化 Sentry 错误追踪"""
    dsn = get_env("SENTRY_DSN")
    if dsn:
        sentry_init(dsn=dsn, environment=os.getenv("ENVIRONMENT", "production"))
        logger.info("Sentry initialized successfully")
    else:
        logger.warning("SENTRY_DSN not configured, error reporting disabled")

def capture_error(error, context=None):
    """捕获并上报错误到 Sentry"""
    try:
        sentry_init()  # 确保已初始化
        exc_info = (type(error), error, sys.exc_info()[2]) if isinstance(error, BaseException) else None
        if exc_info:
            capture_exception(exc_info)
        else:
            capture_exception(error)
        logger.error(f"Error reported to Sentry: {error}")
    except Exception as e:
        logger.error(f"Failed to report error: {e}")

def handle_exception(func):
    """装饰器：捕获函数异常并上报到 Sentry"""
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            capture_error(e, {"function": func.__name__, "args": args, "kwargs": kwargs})
            raise
    return wrapper
