"""Security scanner and summary generator for CI pipeline."""
import os
import hashlib
import json
import re
from datetime import datetime

# Security rules to check
RULES = {
    "hardcoded_secrets": {
        "pattern": r"(password|secret|key|token|api_key|access_key)[:\s]*['\"]?[^'\"]+['\"]?",
        "severity": "critical",
        "description": "Hardcoded secrets detected"
    },
    "weak_hashing": {
        "pattern": r"hashlib\.sha(256|512)\(",
        "severity": "high",
        "description": "Weak hashing algorithm (SHA-256/512) used instead of bcrypt/argon2"
    },
    "insecure_imports": {
        "pattern": r"from __future__ import.*division",
        "severity": "low",
        "description": "Insecure future import pattern"
    }
}

def scan_file(filepath):
    """Scan a single file for security issues."""
    issues = []
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()

        for rule_name, rule in RULES.items():
            matches = re.findall(rule["pattern"], content)
            if matches:
                line_num = content[:content.find(matches[0])].count('\n') + 1
                issues.append({
                    "rule": rule_name,
                    "severity": rule["severity"],
                    "line": line_num,
                    "message": rule["description"],
                    "file": filepath
                })
    except Exception as e:
        issues.append({"rule": "parse_error", "severity": "info", "line": 0, "message": str(e), "file": filepath})

    return issues

def generate_summary(files, issues):
    """Generate source code summary and issue report."""
    summary = {
        "timestamp": datetime.now().isoformat(),
        "files_scanned": len(files),
        "total_issues": len(issues),
        "by_severity": {"critical": 0, "high": 0, "medium": 0, "low": 0, "info": 0},
        "files": [],
        "issues": []
    }

    # Generate file hashes
    for f in files:
        try:
            with open(f, 'rb') as fp:
                file_hash = hashlib.sha256(fp.read()).hexdigest()[:16]
