", "tool_calls": [{"name": "bash", "arguments": "{"command": "cat > ./deploy/restart.sh << 'EOF'\n#!/bin/bash\n# =============================================================================\n# Service Restart Script - Development Team Access\n# =============================================================================\n# Usage: ./restart.sh [options]\n# Options:\n#   --dry-run    Show what would be done without making changes\n#   --force      Force restart even if service is healthy\n#   --help       Show this help message\n# =============================================================================\n\nset -e\n\n# Configuration\nSERVICE_NAME=\"platform-api\"\nPID_FILE=\"/var/run/${SERVICE_NAME}.pid\"\nLOG_FILE=\"/var/log/${SERVICE_NAME}/restart.log\"\nHEALTH_CHECK_URL=\"http://localhost:8080/health\"\nMAX_RETRIES=3\nRETRY_DELAY=5\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\n# Logging function\nlog() {\n    local level=$1\n    shift\n    local message=\"$@\"\n    local timestamp=$(date '+%Y-%m-%d %H:%M:%S')\n    echo \"[$timestamp] [$level] $message\" | tee -a \"$LOG_FILE\"\n}\n\n# Check if service is running\nis_running() {\n    if [ -f \"$PID_FILE\" ]; then\n        local pid=$(cat \"$PID_FILE\")\n        if kill -0 \"$pid\" 2>/dev/null; then\n            return 0\n        fi\n    fi\n    return 1\n}\n\n# Get service PID\nget_pid() {\n    if [ -f \"$PID_FILE\" ]; then\n        cat \"$PID_FILE\"\n    fi\n}\n\n# Health check\nhealth_check() {\n    local retries=0\n    while [ $retries -lt $MAX_RETRIES ]; do\n        if curl -sf \"$HEALTH_CHECK_URL\" > /dev/null 2>&1; then\n            return 0\n        fi\n        retries=$((retries + 1))\n        sleep $RETRY_DELAY\n    done\n    return 1\n}\n\n# Stop service gracefully\nstop_service() {\n    log \"INFO\" \"Stopping $SERVICE_NAME...\"\n    \n    if is_running; then\n        local pid=$(get_pid)\n        log \"INFO\" \"Found running process: PID $pid\"\n        \n        # Graceful shutdown with timeout\n        local timeout=30\n        local elapsed=0\n        while [ $elapsed -lt $timeout ]; do\n            if ! kill -0 \"$pid\" 2>/dev/null; then\n                log \"INFO\" \"Process stopped gracefully\"\n                return 0\n            fi\n            kill -TERM \"$pid\" 2>/dev/null || true\n            sleep 2\n            elapsed=$((elapsed + 2))\n        done\n        \n        # Force kill if still running\n        log \"WARN\" \"Force killing process $pid\"\n        kill -9 \"$pid\" 2>/dev/null || true\n    else\n        log \"INFO\" \"Service not running, nothing to stop\"\n    fi\n}\n\n# Start service\nstart_service() {\n    log \"INFO\" \"Starting $SERVICE_NAME...\"\n    \n    # Check if already running\n    if is_running; then\n        log \"WARN\" \"Service already running (PID: $(get_pid))\"\n        return 1\n    fi\n    \n    # Start the service\n    cd /home/user/project\n    nohup python3 app.py > /var/log/${SERVICE_NAME}.out 2>&1 &\n    local pid=$!\n    \n    # Save PID\n    echo \"$pid\" > \"$PID_FILE\"\n    \n    log \"INFO\" \"Started with PID: $pid\"\n    \n    # Wait for service to be healthy\n    if health_check; then\n        log \"INFO\""}]}

