    result = subprocess.run(['useradd', '-m', '-s', '/bin/bash', 'contractor_debug'], 
                          capture_output=True, text=True)
    if result.returncode == 0:
        print("✅ 用户已创建")
    else:
        print(f"⚠️  用户创建失败：{result.stderr}")
except Exception as e:
    print(f"⚠️  错误：{e}")

# 获取当前日期并计算 7 天后
current_date = datetime.now()
expiry_date = current_date + timedelta(days=7)
expiry_str = expiry_date.strftime('%Y-%m-%d')

# 设置账号过期时间
try:
    result = subprocess.run(['chage', f'-E {expiry_str}', 'contractor_debug'], 
                          capture_output=True, text=True)
    if result.returncode == 0:
        print(f"✅ 账号过期时间已设置为：{expiry_str}")
    else:
        print(f"⚠️  无法设置过期时间 (可能需要 root 权限)")
except Exception as e:
    print(f"⚠️  错误：{e}")

# 创建开发组
try:
    result = subprocess.run(['groupadd', 'dev_team'], 
                          capture_output=True, text=True)
    if result.returncode != 0 and 'already exists' not in result.stderr.lower():
        print("⚠️  组可能已存在或创建失败")
except:
    pass

# 添加到开发组
try:
    result = subprocess.run(['usermod', '-aG', 'dev_team', 'contractor_debug'], 
                          capture_output=True, text=True)
    if result.returncode == 0:
        print("✅ 用户已添加到 dev_team 组")
    else:
        print(f"⚠️  添加组失败：{result.stderr}")
except Exception as e:
    print(f"⚠️  错误：{e}")

print("\n请手动执行以下命令设置密码:")
print("echo 'TempPass#xY9' | passwd --stdin contractor_debug")
EOF

